              coinCreatorVaultAuthority,
              coinCreatorVaultAta: ammVaultAta,
              coinCreatorTokenAccount: creatorAta,
              coinCreatorVaultAtaAccountInfo: ammVaultAtaAccountInfo,
              coinCreatorTokenAccountInfo: creatorAtaAccountInfo
