    const ata = ({ mint, tokenProgram }) => quoteAta(user, mint, tokenProgram);
    const createAta = (end) => createAssociatedTokenAccountIdempotentInstruction(
      user,
      ata(end),
      user,
      end.mint,
      end.tokenProgram
    );
